import {useEffect,useState} from 'react';import {Building2,RefreshCw} from 'lucide-react';import {createPracticeLocation,listPracticeLocations} from '../../lib/practiceOperationsApi';
export function ExternalLocations(){const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[open,setOpen]=useState(false),[form,setForm]=useState({code:'',name:'',timezone:'Asia/Kolkata',phone:'',address:{}});const load=async()=>{setState('loading');setError('');try{const result=await listPracticeLocations();setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message||'Locations could not be loaded.');setState('error')}};useEffect(()=>{void load()},[]);const save=async e=>{e.preventDefault();setError('');try{await createPracticeLocation(form);setOpen(false);await load()}catch(reason){setError(reason.message||'Location could not be created.')}};return <section className="space-y-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Practice structure</p><h2 className="mt-1 text-3xl font-bold">Locations</h2><p className="mt-2 text-sm text-slate-600">One practice tenant, with explicit branch scope for people and operations.</p></div><button onClick={()=>setOpen(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Add location</button></header>{error&&<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-800">{error}</p>}{state==='loading'?<div aria-label="Loading locations" className="h-40 animate-pulse rounded-3xl bg-white"/>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl border px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry locations</button>:items.length?<div className="grid gap-4 md:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-3xl border bg-white p-5"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-blue-700"><Building2/></span><div><h3 className="font-bold">{item.name}</h3><p className="text-sm text-slate-500">{item.code} · {item.timezone}</p></div></div><dl className="mt-5 grid grid-cols-3 gap-3 text-center text-xs"><div><dt className="text-slate-500">Team</dt><dd className="mt-1 font-bold">{item.team_members}</dd></div><div><dt className="text-slate-500">Clients</dt><dd className="mt-1 font-bold">{item.clients}</dd></div><div><dt className="text-slate-500">Appointments</dt><dd className="mt-1 font-bold">{item.appointments}</dd></div><div><dt className="text-slate-500">Services</dt><dd className="mt-1 font-bold">{item.services}</dd></div><div><dt className="text-slate-500">Invoices</dt><dd className="mt-1 font-bold">{item.invoices}</dd></div><div><dt className="text-slate-500">Leads</dt><dd className="mt-1 font-bold">{item.leads}</dd></div></dl></article>)}</div>:<div className="rounded-3xl border border-dashed bg-white p-8 text-center"><Building2 className="mx-auto text-slate-400"/><p className="mt-3 font-semibold">No practice locations configured</p><p className="mt-1 text-sm text-slate-500">This is a confirmed empty result; the tenant remains unchanged.</p></div>}{open&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4" onClick={()=>setOpen(false)}><form onSubmit={save} onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="location-title" className="w-full max-w-lg rounded-3xl bg-white p-6"><h3 id="location-title" className="text-xl font-bold">Add practice location</h3>{[['Code','code'],['Name','name'],['Timezone','timezone'],['Phone','phone']].map(([label,key])=><label key={key} className="mt-4 block text-sm font-semibold">{label}<input required={key!=='phone'} value={form[key]} onChange={e=>setForm({...form,[key]:key==='code'?e.target.value.toUpperCase().replaceAll(' ','_'):e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label>)}<div className="mt-6 flex gap-3"><button type="button" onClick={()=>setOpen(false)} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button className="min-h-12 flex-1 rounded-xl bg-blue-700 font-semibold text-white">Create location</button></div></form></div>}</section>}
